const feed=document.querySelector('#newsFeed'),statusNode=document.querySelector('#newsStatus');let events=[],shown=24,loading=false;
const escapeText=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function httpsURL(s){try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}}
function collectNews(data){if(!Array.isArray(data.games)||!Number.isFinite(Date.parse(data.generated_at)))throw Error('Base inválida');const entries=new Map(data.games.filter(g=>g.repo).map(g=>[g.repo.toLowerCase(),g]));for(const g of CURATED_PROJECTS){const old=entries.get(g.repo.toLowerCase());entries.set(g.repo.toLowerCase(),old?{...g,...old}:g)}const result=[];
 for(const g of entries.values()){if(!['static-recomp','source-port','engine-remake'].includes(g.type)&&!['HarbourMasters/Shipwright','HarbourMasters/2ship2harkinian','coop-deluxe/sm64coopdx','OpenGOAL/jak-project','HarbourMasters/Starship'].some(r=>r.toLowerCase()===g.repo.toLowerCase()))continue;if(/android|ios port/i.test(g.repo+' '+g.title))continue;const url=httpsURL(g.url);if(!url)continue;for(const kind of ['release','activity']){const time=Date.parse(kind==='release'?g.release_date:g.last_commit);if(!Number.isFinite(time)||time>Date.now()||(kind==='release'&&!g.release))continue;result.push({g,kind,time,url:kind==='release'?(httpsURL(g.release_url)||url+'/releases'):url})}}
 return result.sort((a,b)=>b.time-a.time||String(a.g.id).localeCompare(String(b.g.id)));
}
function newsCard(e,index,featured=false){const release=e.kind==='release';return '<article class="'+(featured?'news-highlight':'news-card')+'"><a class="news-cover" href="'+escapeText(projectURL(e.g))+'"><img data-news-index="'+index+'" src="'+escapeText(picture(e.g))+'" alt="'+escapeText(e.g.title)+'" loading="lazy"><span class="news-image-platform">'+escapeText(e.g.platform||'Projeto comunitário')+'</span></a><div class="news-card-body"><div class="news-card-top"><span class="news-kind '+e.kind+'">'+(release?'● NOVA VERSÃO':'↗ EM DESENVOLVIMENTO')+'</span><time datetime="'+new Date(e.time).toISOString()+'">'+new Date(e.time).toLocaleDateString('pt-BR')+'</time></div><h2><a href="'+escapeText(projectURL(e.g))+'">'+escapeText(e.g.title)+'</a></h2><p>'+escapeText(release?'A versão '+e.g.release+' foi publicada. Confira as notas, os arquivos e os requisitos do projeto.':'O repositório recebeu alterações. Veja a atividade mais recente e acompanhe a evolução do projeto.')+'</p><div class="news-card-bottom"><span>'+escapeText(e.g.repo)+'</span><a href="'+escapeText(e.url)+'" target="_blank" rel="noopener noreferrer">'+(release?'Ver versão':'Ver atividade')+' ↗</a></div></div></article>'}
function renderNews(){const query=document.querySelector('#newsSearch').value.toLowerCase().trim(),kind=document.querySelector('#newsType').value;const filtered=events.filter(e=>(kind==='all'||kind===e.kind)&&(e.g.title+' '+e.g.repo).toLowerCase().includes(query));document.querySelector('#newsCount').textContent=filtered.length+(filtered.length===1?' atualização':' atualizações');const feature=document.querySelector('#newsFeature');const featuredIndex=Math.max(0,filtered.findIndex(e=>!picture(e.g).startsWith('data:')));feature.hidden=!filtered.length;feature.innerHTML=filtered.length?newsCard(filtered[featuredIndex],featuredIndex,true):'';feed.innerHTML=filtered.map((e,i)=>({e,i})).filter(({i})=>i!==featuredIndex).slice(0,shown-1).map(({e,i})=>newsCard(e,i)).join('')||(filtered.length?'':'<p class="news-empty">Nenhuma atualização encontrada. Tente outro projeto ou filtro.</p>');document.querySelector('#newsMore').hidden=filtered.length<=shown;document.querySelectorAll('[data-news-index]').forEach(img=>bindImageFallback(img,filtered[Number(img.dataset.newsIndex)].g))}
async function refreshNews(){if(loading)return;loading=true;document.querySelector('#newsRefresh').disabled=true;statusNode.textContent='Consultando a fonte…';try{const r=await fetch('https://raw.githubusercontent.com/SubmitGame/awesome-decomp-games/main/data/games.json',{cache:'no-cache',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const d=await r.json();events=collectNews(d);renderNews();statusNode.textContent='Fonte atualizada em '+new Date(d.generated_at).toLocaleString('pt-BR');try{localStorage.setItem('atlas-news',JSON.stringify(d))}catch{}}catch{statusNode.textContent=events.length?'Sem conexão com a fonte. Exibindo a última base disponível.':'Não foi possível carregar as novidades. Tente atualizar.'}finally{loading=false;document.querySelector('#newsRefresh').disabled=false}}
async function initNews(){let best=null;try{const d=JSON.parse(localStorage.getItem('atlas-news'));if(d){collectNews(d);best=d}}catch{}try{const r=await fetch('catalog.json');if(!r.ok)throw Error();const d=await r.json();collectNews(d);if(!best||Date.parse(d.generated_at)>Date.parse(best.generated_at))best=d}catch{}if(best){events=collectNews(best);renderNews()}await refreshNews()}
document.querySelector('#newsSearch').addEventListener('input',()=>{shown=24;renderNews()});document.querySelector('#newsType').addEventListener('change',()=>{shown=24;renderNews()});document.querySelector('#newsRefresh').onclick=refreshNews;document.querySelector('#newsMore').onclick=()=>{shown+=24;renderNews()};setInterval(()=>{if(!document.hidden)refreshNews()},1800000);initNews();
